mapper.select:
SELECT a.STATUS, a.RELORG_ID, a.ORGAN_NAME, a.CREATE_USER, a.CREATE_TIME as createTime, a.UPDATE_USER, a.UPDATE_TIME as updateTime, a.SVR_DATA_SOURCES as svrDataSources FROM rep_relorg a
and (a.RELORG_ID like concat('%',concat(#{relorgId,jdbcType=VARCHAR},'%')) or a.ORGAN_NAME like concat('%',concat(#{relorgId,jdbcType=VARCHAR},'%')) )
#{status,jdbcType=VARCHAR}

mapper.update:
UPDATE rep_relorg
set
STATUS = #{status,jdbcType=VARCHAR},SVR_DATA_SOURCES=#{svrDataSources,jdbcType=VARCHAR},
ORGAN_NAME= #{organName,jdbcType=VARCHAR}
where
RELORG_ID= #{relorgId,jdbcType=VARCHAR}
